SELECT o.id,(SELECT i.label FROM model_rows i WHERE i.id=o.id),(SELECT (SELECT o.value)),EXISTS(SELECT o.label WHERE o.id>0 ORDER BY (SELECT o.nullable)),(SELECT count(*) FROM model_rows i WHERE i.id>0 ORDER BY (SELECT i.label)),(SELECT sum(EXISTS(SELECT i.label)) FROM model_rows i),(SELECT count(*) FROM model_rows i ORDER BY (SELECT o.label)) FROM model_rows o ORDER BY o.id LIMIT 4;
